        string st;
        for (char ch : s) {
            if (!st.empty() && st.back() != ch &&
                tolower(static_cast<unsigned char>(st.back())) ==
                tolower(static_cast<unsigned char>(ch))) {
                st.pop_back();
            } else {
                st.push_back(ch);
            }
        }
        return st;
    }
};

