function makeGood(s) {
    const stack = [];
    for (const ch of s) {
        if (stack.length > 0 && stack[stack.length - 1] !== ch &&
            stack[stack.length - 1].toLowerCase() === ch.toLowerCase()) {
            stack.pop();
        } else {
            stack.push(ch);
        }
    }
    return stack.join('');
}

