static int is_bad_pair(char a, char b) {
    if (a == b) return 0;
    if ('a' <= a && a <= 'z' && 'A' <= b && b <= 'Z') return a - 'a' == b - 'A';
    if ('A' <= a && a <= 'Z' && 'a' <= b && b <= 'z') return a - 'A' == b - 'a';
    return 0;
}

static char *makeGood(const char *s) {
    size_t n = strlen(s);
    char *stack = (char *)malloc(n + 1);
    if (!stack) return NULL;
    size_t top = 0;
    for (size_t i = 0; i < n; ++i) {
        char ch = s[i];
        if (top > 0 && is_bad_pair(stack[top - 1], ch)) {
            --top;
        } else {
            stack[top++] = ch;
        }
    }
    stack[top] = '\0';
    return stack;
}

